  'delivery.kind.appointment_update': 'अपॉइंटमेंट में बदलाव',

  'clinicOps.title': 'क्लिनिक सत्र में बदलाव',
  'clinicOps.intro':
    'सत्र की अपॉइंटमेंट रद्द करने, दूसरे समय ले जाने या देरी बताने से पहले पूर्वावलोकन देखें और पुष्टि करें। चुनी अवधि की सभी योग्य अपॉइंटमेंट साथ सँभाली जाती हैं।',
  'clinicOps.policy':
    'रद्द करने या समय बदलने में बिल, अग्रिम भुगतान, शुरू हो चुके इलाज या चिकित्सा रिकॉर्ड वाली अपॉइंटमेंट अलग समीक्षा के लिए रहती हैं। यहाँ रिफंड या बिल स्थानांतरण नहीं होता। रद्द या स्थानांतरण से मूल अवधि में नई बुकिंग बंद होती है। देरी केवल अनुमान है; बुक किया समय नहीं बदलता।',
  'clinicOps.action': 'बदलाव का प्रकार',
