  'clinicOps.notify':
    'अपॉइंटमेंट संदेशों की सहमति वाले नंबरों के लिए अतिरिक्त WhatsApp सूचना कतार में लगाएँ',
  'clinicOps.notConfigured':
    'स्वचालित बदलाव सूचना अभी सेट नहीं है। प्रभावित मरीजों से संपर्क करें; क्रेडेंशियल और स्वीकृत टेम्पलेट बाद में जोड़े जा सकते हैं।',
  'clinicOps.confirmationNote':
    'नई अपॉइंटमेंट की सामान्य पुष्टि और याद दिलाने वाले संदेश अलग सहमति सेटिंग के अनुसार कतार में लग सकते हैं। पुराने अंतराल बनाए रहते हैं; समान खाली स्लॉट वाला नया सत्र चुनें।',
